const EXPECTED_SOURCE_PATHS = Object.freeze([
  "packages/core/src/ir/semantics/portable-scalar-domain.ts",
  "packages/core/src/ir/semantics/runner-machine-scope.ts",
  "packages/core/src/ir/semantics/semantic-atomic-ownership.ts",
  "packages/core/src/ir/semantics/semantic-clone.ts",
  "packages/core/src/ir/semantics/semantic-env.ts"
]);
const EXPECTED_COMPILED_PATHS = Object.freeze([
  "ir/semantics/portable-scalar-domain.js",
  "ir/semantics/runner-machine-scope.js",
  "ir/semantics/semantic-atomic-ownership.js",
  "ir/semantics/semantic-clone.js",
  "ir/semantics/semantic-env.js"
]);

function exactRows(rows, expectedPaths) {
  return (
    Array.isArray(rows) &&
    rows.length === expectedPaths.length &&
    rows.every((row, index) =>
      row?.claim === CLAIM &&
      row.path === expectedPaths[index] &&
      /^[0-9a-f]{64}$/u.test(row.currentDigest) &&
      /^[0-9a-f]{64}$/u.test(row.expectedDigest) &&
      Array.isArray(row.replacements) &&
      row.replacements.length > 0
    )
  );
}

export function executionMetadataHardeningCompiledReconstruction(path) {
  return POST_EXECUTION_METADATA_HARDENING_COMPILED_RECONSTRUCTIONS.find((row) => row.path === path);
}

export function validateExecutionMetadataHardeningHistoricalTransition({
  transition = EXECUTION_METADATA_HARDENING_HISTORICAL_TRANSITION,
  sourceReconstructions = POST_EXECUTION_METADATA_HARDENING_SOURCE_RECONSTRUCTIONS,
  compiledReconstructions = POST_EXECUTION_METADATA_HARDENING_COMPILED_RECONSTRUCTIONS,
} = {}) {
  if (
    transition?.claim !== CLAIM ||
    transition.predecessorCommit !== PREDECESSOR_COMMIT ||
    transition.successorCommit !== SUCCESSOR_COMMIT ||
    JSON.stringify(transition.sourceManifest) !== '{"count":5,"digest":"b591febc7a8acd10402785c9b322019c19d0b810b02ad9c459ecb50a8eaa091a"}' ||
    JSON.stringify(transition.compiledManifest) !== '{"count":5,"digest":"3ded33e9cfd98c847e3337e54444e31f3aaff9d5e964e17479dbc28827fadee4"}' ||
    JSON.stringify(transition.sourceEndpoints) !== '{"predecessor":"4fa812506f62cb2a7271f74fe46023d5efc8e7aebf03641e7beea77da04d20b4","successor":"eaaa6b309a8cb8f05bcfe77ccfefa96d96868f4d0b7fdab5802d91b6ae03e71a"}' ||
    JSON.stringify(transition.compiledEndpoints) !== '{"predecessor":"b79daaea1090fb7c7592a93de6353db89ea8d356b5f204ddcfe8826aabed1ee8","successor":"9c1351a27a3e465e7884e4618ef932a19ca27322c1fd6f5bf7a209a0c453696e"}' ||
    JSON.stringify(transition.compiledInventory?.predecessor) !== '{"count":317,"digest":"34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67"}' ||
    JSON.stringify(transition.compiledInventory?.successor) !== '{"count":317,"digest":"34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67"}' ||
    !exactRows(sourceReconstructions, EXPECTED_SOURCE_PATHS) ||
    !exactRows(compiledReconstructions, EXPECTED_COMPILED_PATHS)
  ) {
    throw new TypeError('execution-metadata hardening historical transition immutable identity changed');
  }
  return true;
}
